import {logList} from "@/api/safeDanger/report";

export default {
  name: "workLog",
  props: {
    detailId: {
      // type: Number,
      require: false
    },
    workflowId: {
      require: false
    }
  },
  data() {
    return {
      // 查询参数
      queryParams: {
        pageNum: 1,
        pageSize: 20,
        hiddenId: undefined,
      },
      // 总条数
      total: 0,
      // 已办列表表格数据
      activeLogList: [],
      // 弹出层标题
      title: "",
      //遮罩层
      loading: false
    }
  },
  created() {

  },
  mounted() {
    this.getList();
  },
  methods: {
    /** 查询已办列表 */
    getList() {
      this.loading = true;
      this.queryParams.hiddenId = this.detailId || 0
      logList(this.queryParams).then(response => {
          this.activeLogList = response.rows;
          this.total = response.total;
        }
      ).finally(() => {
        this.loading = false;
      });
    },

    //设置行样式
    rowStyle({row, rowIndex}) {
      let styleJson = {}
      // if ("2" === row.currentState) {
      //   styleJson = {
      //     'color' : 'red'
      //   }
      // }else {

      // }
      let totalPage = Math.ceil(this.total / this.queryParams.pageSize)
      if (rowIndex === this.activeLogList.length - 1 && this.queryParams.pageNum == totalPage) {
        if (row.hiddenLog) {
          if (row.hiddenLog.includes('不通过')) {
            styleJson = {
              'color': '#E63F32',
              'font-weight': 'bold'
            }
          } else {
            styleJson = {
              'color': '#006F6B',
              'font-weight': 'bold'
            }
          }
        } else {
          styleJson = {
            'color': '#006F6B',
            'font-weight': 'bold'
          }
        }
      }
      return styleJson
    }
  }
}
